def _loai_noi_bat(bi_loai: list[tuple[SanPham, str, str]]) -> LyDoLoai | None:
    """Chon may bi loai DANG noi nhat: re nhat trong so bi loai vi cong suat.

    Vi sao re nhat: do chinh la may khach hay thay quang cao gia tot va dang
    nham toi. Khong noi truoc thi khach se hoi 'sao khong thay may X?'.
    """
    ung = [x for x in bi_loai if x[1] == "cong_suat"]
    if not ung:
        return None
    sp, ly_do, chi_tiet = min(ung, key=lambda x: x[0].gia)
    return LyDoLoai(ma_sp=sp.ma_sp, ten=sp.ten, ly_do=ly_do, chi_tiet=chi_tiet)

