function veSanPham(u, i){
  let s = '<div class="the-sp"><div class="hang-to"><b>' + (i+1) + '. ' + u.ten + '</b>'
        + '<span class="gia">' + u.gia.toLocaleString('vi-VN') + 'đ</span></div>';
  (u.hon||[]).forEach(h => s += '<div class="to hon">+ Hơn về ' + h.truc + ': ' + h.cua_minh + ' (so với ' + h.doi_thu + ')</div>');
  (u.kem||[]).forEach(k => s += '<div class="to kem">− Kém về ' + k.truc + ': ' + k.cua_minh + ' (so với ' + k.doi_thu + ')</div>');
  s += '<div>';
  (u.nguon||[]).forEach(n => {
    if (n.gia_tri && n.gia_tri !== 'None')
      s += '<button class="badge" onclick=\'moNguon(' + JSON.stringify(n).replace(/'/g,"&#39;") + ')\'>' + n.truong + ' ⓘ</button>';
  });
  return s + '</div></div>';
}

input.new_string:
function veSanPham(u, i){
  // Gia khuyen mai: co gia_goc > gia ban -> gach gia goc + badge % giam (so
  // % tinh tu 2 gia THAT trong catalog, khong phai so trang tri).
  const ng = (u.nguon||[]).find(n => n.truong === 'gia_goc');
  const gg = ng ? parseFloat(ng.gia_tri) : null;
  let giaHtml = '<span class="gia">';
  if (gg && gg > u.gia){
    const pt = Math.round((1 - u.gia/gg) * 100);
    giaHtml = '<span class="gia"><span class="gia-goc">' + gg.toLocaleString('vi-VN') + 'đ</span> ';
    giaHtml += u.gia.toLocaleString('vi-VN') + 'đ<span class="giam">-' + pt + '%</span></span>';
  } else {
    giaHtml += u.gia.toLocaleString('vi-VN') + 'đ</span>';
  }
  let s = '<div class="the-sp"><div class="hang-to"><b>' + (i+1) + '. ' + u.ten + '</b>' + giaHtml + '</div>';
  (u.hon||[]).forEach(h => s += '<div class="to hon">✓ ' + (h.truc === 'giá' ? 'Rẻ hơn' : 'Nhỉnh hơn về ' + h.truc) + ': ' + h.cua_minh + ' (so với ' + h.doi_thu + ')</div>');
  (u.kem||[]).forEach(k => s += '<div class="to kem">△ ' + (k.truc === 'giá' ? 'Đắt hơn' : 'Chịu thiệt về ' + k.truc) + ': ' + k.cua_minh + ' (so với ' + k.doi_thu + ')</div>');
  s += '<div>';
  (u.nguon||[]).forEach(n => {
    if (n.gia_tri && n.gia_tri !== 'None')
      s += '<button class="badge" onclick=\'moNguon(' + JSON.stringify(n).replace(/'/g,"&#39;") + ')\'>' + nhan(n.truong) + ' ⓘ</button>';
  });
  s += '</div>';
  if (i > 0)
    s += '<button class="nut-ss" onclick="guiVB(\'so sánh máy 1 và máy ' + (i+1) + '\')">⚖ So sánh với máy 1</button>';
  return s + '</div>';
}

