input.new_string:
async function docTo(text){
  // Lam sach de DOC (khong dong den hien thi): bo markdown/bullet, dau '—' va
  // '·' thanh khoang trang (TTS ngat qua lau o dau cau), '/' doc 'trên'
  // (kWh/năm), gia '7.960.000đ' doc thanh chu '7 triệu 960 nghìn đồng'.
  const sach = text
    .replace(/\*\*/g, '')
    .replace(/^[•✓△→-]\s*/gm, '')
    .replace(/(\d+)\.(\d{3})\.(\d{3})\s*đ/g, (m, a, b) =>
      a + ' triệu ' + (b !== '000' ? parseInt(b) + ' nghìn ' : '') + 'đồng')
    .replace(/anh\/chị/gi, 'anh chị')
    .replace(/[—–·]/g, ' ')
    .replace(/\//g, ' trên ')
    .replace(/\s{2,}/g, ' ')
    .slice(0, 400);

