body{font-family:system-ui,-apple-system,"Segoe UI",Roboto,sans-serif;background:var(--nen);color:var(--muc);height:100vh;display:flex;flex-direction:column}
header{background:var(--the);border-bottom:1px solid var(--vien);padding:14px 20px;display:flex;align-items:center;gap:10px}
header b{font-size:17px;color:var(--chinh)}
header span{font-size:13px;color:var(--phu)}
main{flex:1;display:flex;min-height:0;max-width:1080px;width:100%;margin:0 auto;gap:0}
#khung{flex:1;overflow-y:auto;padding:20px;min-width:0}
/* ── Panel trai: mat bot (nhep mieng theo giong doc) + o anh san pham ── */
#ben-trai{width:250px;flex-shrink:0;padding:20px 14px;display:flex;flex-direction:column;gap:14px;border-right:1px solid var(--vien)}
@media (max-width:900px){#ben-trai{display:none}}
.the-panel{background:var(--the);border:1px solid var(--vien);border-radius:14px;padding:14px;text-align:center}
.mat{width:96px;height:96px;border-radius:50%;background:linear-gradient(145deg,var(--chinh),#003db3);margin:4px auto 10px;position:relative}
.mat .mat-trai,.mat .mat-phai{position:absolute;top:34px;width:12px;height:16px;border-radius:50%;background:#fff}
.mat .mat-trai{left:24px}.mat .mat-phai{right:24px}
.mat .mieng{position:absolute;left:50%;transform:translateX(-50%);bottom:22px;width:30px;height:6px;border-radius:0 0 16px 16px;background:#fff;transition:height .12s}
.mat.dang-noi .mieng{animation:nhep .28s infinite alternate}
.mat.dang-noi .mat-trai,.mat.dang-noi .mat-phai{animation:chop 3s infinite}
@keyframes nhep{from{height:5px}to{height:16px;border-radius:10px}}
@keyframes chop{0%,92%,100%{transform:scaleY(1)}96%{transform:scaleY(.1)}}
.ten-bot{font-weight:700;font-size:14.5px}
.trang-thai{font-size:12px;color:var(--phu);margin-top:2px}
.mat.dang-noi ~ .trang-thai{color:var(--chinh)}
#o-anh .khung-anh{height:120px;border:1.5px dashed var(--vien);border-radius:10px;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:6px;color:var(--phu);font-size:12px;margin-top:8px}
#o-anh .khung-anh .bieu-tuong{font-size:34px}
#o-anh .ten-sp{font-weight:700;font-size:13.5px;margin-top:8px;color:var(--muc)}
#o-anh .gia-sp{color:var(--chinh);font-weight:700;font-size:14px}

