// ── Mat bot: nhep mieng dung luc dang phat tieng (ca TTS FPT lan trinh duyet)
const matBot = document.getElementById('mat-bot');
const trangThai = document.getElementById('trang-thai');
function batMieng(){ if (matBot) { matBot.classList.add('dang-noi'); trangThai.textContent = 'Đang nói...'; } }
function tatMieng(){ if (matBot) { matBot.classList.remove('dang-noi'); trangThai.textContent = 'Sẵn sàng tư vấn'; } }

// ── O "san pham dang xem": bam card top 3 -> hien o panel trai.
// Anh THAT chua co (du lieu DMX khong kem link anh) -> ghi ro cho Image API,
// khong do anh gia - dung luat "khong bia" ke ca bang hinh.
function chonSP(sp){
  const o = document.getElementById('o-anh');
  if (!o) return;
  const giam = sp.gg && sp.gg > sp.gia
    ? ' <span class="giam">-' + Math.round((1 - sp.gia / sp.gg) * 100) + '%</span>' : '';
  o.innerHTML = '<div style="font-size:12.5px;color:var(--phu);text-align:left">SẢN PHẨM ĐANG XEM</div>'
    + '<div class="khung-anh"><span class="bieu-tuong">🖼️</span><span>Ảnh thật: chờ nối<br>Image API của ĐMX</span></div>'
    + '<div class="ten-sp">' + sp.ten + '</div>'
    + '<div class="gia-sp">' + sp.gia.toLocaleString('vi-VN') + 'đ' + giam + '</div>';
}

