import openpyxl
wb = openpyxl.load_workbook('data/raw/Spec_cate_gia.xlsx', data_only=True, read_only=True)
ws = wb['Máy lạnh']
rows = ws.iter_rows(values_only=True)
hdr = list(next(rows))
im, ip = hdr.index('model_code'), hdr.index('productidweb')
tim = {'334018'}
for r in rows:
    mc, pw = str(r[im] or ''), str(r[ip] or '')
    if mc in tim or pw in tim:
        print('KHOP! model_code=', mc, '| productidweb=', pw, '| brand=', r[hdr.index('brand')])
        break
else:
    # in vai vi du 2 cot de doi chieu dinh dang
    wb2 = openpyxl.load_workbook('data/raw/Spec_cate_gia.xlsx', data_only=True, read_only=True)
    ws2 = wb2['Máy lạnh']; rows2 = ws2.iter_rows(values_only=True); next(rows2)
    for i, r in enumerate(rows2):
        if i < 5:
            print('vd: model_code=', r[im], '| productidweb=', r[ip])
        else:
            break
EOF

