(function khoiTaoMat(){
  const cv = document.getElementById('mat-3d');
  if (!cv) return;
  cv.width = 280; cv.height = 280;                 // ve 2x roi CSS thu ve 140 -> net
  const c = cv.getContext('2d');
  may3d = {dichMo: 0, dichRong: 1, mo: 0, rong: 1, gat: 0, chop: 0, tNhay: 0};

  const anh = new Image();
  let anhOk = false;
  anh.onload = () => { anhOk = true; };
  anh.src = '/static/co-gai.png';

  // Duong khe moi do tren anh goc 1254px, quy ve khung canvas 280px.
  const K = 280 / 1254;
  const seamPts = [[525,758],[550,770],[574,781],[598,788],[622,796],
                   [646,797],[670,796],[694,794],[725,786]].map(p => [p[0]*K, p[1]*K]);
  const xc1 = seamPts[0][0], xc2 = seamPts[seamPts.length-1][0];
  function seamY(x){
    if (x <= xc1) return seamPts[0][1];
    if (x >= xc2) return seamPts[seamPts.length-1][1];
    for (let i = 1; i < seamPts.length; i++)
      if (x <= seamPts[i][0]) {
        const [x0,y0] = seamPts[i-1], [x1,y1] = seamPts[i];
        return y0 + (y1-y0)*(x-x0)/(x1-x0);
      }
    return seamPts[seamPts.length-1][1];
  }
  const D = 13, jawH = 50;

  function khung(t){
    requestAnimationFrame(khung);
    const s = t/1000, m = may3d;
    m.dichMo += ((dangNoi ? .05 : 0) - m.dichMo) * .09;
    m.mo += (m.dichMo - m.mo) * .35;
    m.rong += (m.dichRong - m.rong) * .22;
    m.gat *= .9;
    if (s > m.tNhay) { m.tNhay = s + 2.4 + Math.random() * 2.6; m.chop = 1; }
    if (m.chop > 0) m.chop -= .11;
    const bien = dangNoi ? 1 : .35;
    const sway = Math.sin(s*.8)*.016 + Math.sin(s*1.9)*.011*bien;
    const bob = Math.sin(s*1.25)*(dangNoi ? 1.6 : .9) + m.gat*5;

    c.setTransform(1,0,0,1,0,0);
    c.clearRect(0,0,280,280);
    c.save();

