nutAnh.onclick = () => oAnhIn.click();
oAnhIn.onchange = async () => {
  const f = oAnhIn.files[0]; oAnhIn.value = '';
  if (!f) return;
  them('📷 <i>Đang gửi ảnh cho AI đọc…</i>', 'khach');
  const cho = them('<span class="cham"><i></i><i></i><i></i></span>', 'bot');
