    const b64 = await nenAnh(f);          // resize + base64, bo tien to data URI
    const r = await fetch('/api/nhin-anh', {
      method: 'POST', headers: {'Content-Type': 'application/json'},
      body: JSON.stringify({anh_b64: b64, dinh_dang: 'jpeg'})
    });
